import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators: WeakMap<object, ValidateFunction>;
}

interface SafeValidationError {
  instancePath?: string;
  keyword: string;
  params: Record<string, unknown>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(`Unable to compile inputSchema for tool ${resolved.name}: ${message}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator, validators: new WeakMap()});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a tool, returning schema rejections and throwing only for unknown names; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.validatorFor(tool, definition);
    if (validator && !validator(input)) {
      return {result: `Invalid tool input: ${this.validationDetail(validator)}`};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    const cached = tool.validators.get(definition.inputSchema);
    if (cached) return cached;
    try {
      const validator = this.ajv.compile(definition.inputSchema);
      tool.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Unable to compile inputSchema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  private validationDetail(validator: ValidateFunction): string {
    const error = validator.errors?.[0] as SafeValidationError | undefined;
    if (!error) return 'input must be valid';
    const path = error.instancePath ? `input${error.instancePath.replaceAll('/', '.')}` : 'input';
    const missingProperty = error.keyword === 'required' ? error.params.missingProperty : undefined;
    if (typeof missingProperty === 'string') return `${path}.${missingProperty} is required`;
    const property = error.params.property;
    const propertyPath = typeof property === 'string' ? `${path}.${property}` : path;
    const expectedType = error.params.type;
    return `${propertyPath} must be ${typeof expectedType === 'string' ? expectedType : error.keyword}`;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {name: 'get_weather', description: 'Weather', inputSchema: {required: ['location']}},
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required/i),
    });
  });

  it('rejects a wrong-typed property with its field and expected type without leaking its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup',
        description: 'Lookup',
        inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']},
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup', {ssn: 123456789});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/ssn.*string/i),
    });
  });

  it('reuses a static schema validator across ten executions', async () => {
    const registry = new ToolRegistry();
    const inputSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    let executorCalls = 0;
    registry.register({name: 'get_weather', description: 'Weather', inputSchema}, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    inputSchema.required = ['unrelated'];
    const responses = await Promise.all(
      Array.from({length: 10}, () => registry.execute('get_weather', {location: 'Paris'}))
    );

    expect({executorCalls, results: responses.map(response => response.result)}).toEqual({
      executorCalls: 10,
      results: Array(10).fill('sunny'),
    });
  });

  it('names the nested field path when a property has the wrong type', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile_lookup',
        description: 'Lookup a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {email: {type: 'string'}}}},
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('profile_lookup', {profile: {email: 42}});

    expect(response.result).toMatch(/input\.profile\.email.*string/i);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.test.ts#L4), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property with its field and expected type without leaking its value](../../src/orchestration/tools/registry.test.ts#L23), [validated by: names the nested field path when a property has the wrong type](../../src/orchestration/tools/registry.test.ts#L69), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reuses a static schema validator across ten executions](../../src/orchestration/tools/registry.test.ts#L46)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
